                  </div>
                </div>

                {/* Category Breakdown (Detailed) */}
                <div className="space-y-4">
                  <h4 className="text-xs font-semibold tracking-widest text-zinc-400 uppercase">
                    Category Breakdown
                  </h4>
                  <div className="space-y-4">
                    {breakdown.map((item, idx) => {
