} from '@hugeicons/core-free-icons';
import { cn } from '@/lib/utils';

export interface CardItem {
  id: number;
  title: string;
  description: string;
  icon: (theme: 'light' | 'dark') => ReactNode;
}

interface CardCarouselProps {
  items?: CardItem[];
}

const DEFAULT_CARDS: CardItem[] = [
  {
