  {
    id: 'subscriptions',
    name: 'Subscriptions',
    items: [
      {
        id: 's-1',
        name: 'Streaming',
        price: 80,
        icon: TbPlayerPlayFilled,
      },
      {
        id: 's-2',
        name: 'Courses',
        price: 100,
        icon: FaGraduationCap,
      },
      {
        id: 's-3',
        name: 'Software & Apps',
        price: 120,
        icon: BsFillMouse2Fill,
      },
      {
        id: 's-4',
        name: 'Games',
        price: 50,
        icon: IoGameController,
      },
    ],
  },
  {
    id: 'daily-needs',
    name: 'Daily Needs',
    items: [
      {
        id: 'dn-1',
        name: 'Groceries',
        price: 500.56,
        icon: FaCarrot,
      },
      {
        id: 'dn-2',
        name: 'Snacks',
        price: 45.2,
        icon: Coffee,
      },
      {
        id: 'dn-3',
        name: 'Essentials',
        price: 120.34,
        icon: TbHomeFilled,
      },
      {
        id: 'dn-4',
        name: 'Health',
        price: 75.8,
        icon: FaPills,
      },
    ],
  },
];

const springConfig: Transition = {
  type: 'spring',
  stiffness: 200,
  damping: 20,
  mass: 1.1,
};

export const DisclosureCard: FC<DisclosureCardProps> = ({
  collections = DEFAULT_COLLECTIONS,
}) => {
  return (
    <div className="flex w-full items-center justify-center">
      <motion.div
        className="flex flex-col gap-2 will-change-transform"
        layout="position"
        transition={springConfig}
      >
        {collections.map((collection) => (
          <GridContainer
            key={collection.id}
            title={collection.name}
            items={collection.items}
          />
        ))}
      </motion.div>
    </div>
  );
};

const GridContainer = ({
  items,
  title,
}: {
  items: CollectionItem[];
  title: string;
}) => {
  const [isExpanded, setIsExpanded] = useState(false);
  const [ref, bounds] = useMeasure({ offsetSize: true });

  return (
    <MotionConfig transition={springConfig}>
      <motion.div
        className="w-[300px] cursor-pointer overflow-hidden rounded-lg border border-gray-200 bg-zinc-100 dark:border-zinc-700 dark:bg-zinc-800"
        animate={{
          height: bounds.height > 0 ? bounds.height : "auto"
        }}
      >
        <div className="p-2" ref={ref}>
          <AnimatePresence
            mode="popLayout"
            key={isExpanded ? 'expanded' : 'collapsed'}
            propagate
          >
            {!isExpanded ? (
              <motion.div
                key={'collapsed'}
                className="flex w-full items-center space-x-2"
                onClick={() => setIsExpanded(true)}
                exit={{ opacity: 0 }}
                transition={{ duration: 0.1, ease: 'easeOut' }}
              >
                <div className="grid grid-cols-2 gap-1">
                  {items.map((item, index) => (
                    <motion.div
                      className="relative flex size-6 items-center justify-center rounded-full bg-zinc-300 p-1 dark:bg-white"
                      key={`${item.name}-${index}`}
                      layoutId={`${item.name}`}
                      transition={{ ...springConfig, delay: 0.01 }}
                    >
                      <item.icon className="size-4 fill-white dark:fill-black" />
                    </motion.div>
                  ))}
                </div>

                <div className="ml-2 flex flex-1 flex-col items-start justify-center">
                  <motion.span
                    layoutId={`title-${title}`}
                    layout="position"
                    className="text-lg text-zinc-900 dark:text-zinc-100"
                  >
                    {title}
                  </motion.span>
                  <span className="text-sm text-zinc-500 dark:text-zinc-400">
                    {items.length} Items
                  </span>
