'use client';

import React, { useState, useEffect, useRef } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import {
  Maximize2,
  X,
  Globe,
  GitBranch,
  GitCommit,
  Play,
  CheckCircle2,
  MoreVertical,
  Terminal,
  Search,
  Box,
  RotateCw,
  Copy,
  History,
  Settings,
  ShieldCheck,
  AlertCircle,
} from 'lucide-react';
import { PiShareFatLight, PiCheckBold } from 'react-icons/pi';
import { LuClock } from 'react-icons/lu';
import { TbArrowUpRight, TbCircleDashed } from 'react-icons/tb';
import { BsCalendar4Week } from 'react-icons/bs';
import { HiMiniCalendar } from 'react-icons/hi2';
import { cn } from '@/lib/utils';

// --- Interfaces  ---
export interface DeploymentStep {
  id: string;
  label: string;
  status: 'success' | 'warning' | 'error' | 'loading' | 'pending';
  progress: number;
  duration: string;
  metrics?: { files: number; functions: number; assets: number; size: string };
  errors?: number;
  warnings?: number;
}

export interface DeploymentData {
  id: string;
  environment: string;
  status: 'Ready' | 'Building' | 'Error';
  createdTime: string;
  createdBy: { name: string; avatar: string };
  duration: string;
  lastActive: string;
  domains: string[];
  branch: string;
  commitMessage: string;
  commitHash: string;
  steps: DeploymentStep[];
}

// --- Components ---

const SegmentedProgress = ({
  progress,
  status,
  count = 22,
}: {
  progress: number;
  status: string;
  count?: number;
}) => {
  const activeSegments = Math.floor(progress * count);
  return (
    <div className="flex gap-0.5">
      {Array.from({ length: count }).map((_, i) => {
        const isActive = i < activeSegments;
        let color = 'bg-neutral-200 dark:bg-[#1e1e1f]';
        if (isActive) {
          color =
            status === 'error'
              ? 'bg-red-500'
              : status === 'warning'
                ? 'bg-amber-500'
                : 'bg-[#22c55e]';
        }
        return (
          <div
            key={i}
            className={cn(
              'h-2.5 w-1 rounded-[1px] transition-colors duration-150',
              color,
            )}
          />
        );
      })}
    </div>
  );
};

const MetricTag = ({
  label,
  value,
}: {
  label: string;
  value: string | number;
}) => (
