// --- Components ---

const SegmentedProgress = ({
  progress,
  status,
  count = 22,
}: {
  progress: number;
  status: string;
  count?: number;
}) => {
  const activeSegments = Math.floor(progress * count);
  return (
    <div className="flex gap-0.5">
      {Array.from({ length: count }).map((_, i) => {
        const isActive = i < activeSegments;
        let color = 'bg-neutral-200 dark:bg-[#1e1e1f]';
        if (isActive) {
          color =
            status === 'error'
              ? 'bg-red-500'
              : status === 'warning'
                ? 'bg-amber-500'
                : 'bg-[#22c55e]';
        }
        return (
          <div
