            <AnimatePresence mode="wait">
              {isEditingDate ? (
                <motion.input
                  key="edit-date"
                  initial={{ opacity: 0 }}
                  animate={{ opacity: 1 }}
                  exit={{ opacity: 0 }}
                  value={date}
                  onChange={(e) => setDate(e.target.value)}
                  onKeyDown={(e) =>
