const SPRING_CONFIG = {
  type: 'spring',
  stiffness: 200,
  damping: 22,
  mass: 1.2,
} as const;

export default function ExpandDetails() {
  const [isOpen, setIsOpen] = useState(true);
  const [ref, bounds] = useMeasure({ offsetSize: true });

