} from 'motion/react';
import { FaArrowUp } from 'react-icons/fa6';

export interface FundItem {
  id: string;
  label: string;
  value: string;
  change: string;
}

interface FundWidgetProps {
  data?: FundItem[];
  initialIndex?: number;
}

const DEFAULT_DATA: FundItem[] = [
  {
    id: 'stocks',
    label: 'Stocks',
    value: '2.7Cr',
    change: '12%',
  },
  {
    id: 'funds',
    label: 'Funds',
