interface EditableRowProps {
  icon: any;
  label: string;
  value: string;
  secondaryValue?: string;
  onSave?: (value: string) => void;
  onSaveRange?: (v1: string, v2: string) => void;
  type?: 'text' | 'time' | 'url';
  multiline?: boolean;
}

