                                      const globalIndex =
                                        priorLength +
                                        previousLengths +
                                        charIndex;

                                      return (
                                        <motion.span
                                          key={`char-${charIndex}-${currentEntry.id}`}
                                          custom={globalIndex}
                                          variants={charVariants}
