                                      );
                                    },
                                  )}
                                </motion.span>
                              );
                            })}
                          </motion.p>
                        );
                      })}
                    </motion.div>
                  ) : (
                    currentEntry.content
                  )}
                </motion.div>
              </AnimatePresence>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

