            <div className="flex items-center gap-2 sm:gap-3 min-w-0">
              <motion.div
                animate={{ rotate: isExpanded ? 0 : 180 }}
                className="w-7 h-7 sm:w-8 sm:h-8 rounded-lg flex items-center justify-center text-[#A1A1A1] shrink-0"
