                              ? 'bg-[#292929] dark:bg-[#EDEDED] border-[#292929] dark:border-[#EDEDED] shadow-sm shadow-[#1a1919] text-white dark:text-[#1A1A1A]'
                              : 'border-[#E5E5E7] dark:border-[#333] text-[#A1A1A1] dark:text-[#555] shadow-sm shadow-[#8f8e8e]/40'
