watermelon/animated/quick-feedback.code:
'use client';

import { type FC, useState } from 'react';
import {
  motion,
  AnimatePresence,
  type Transition,
  MotionConfig,
  LayoutGroup,
} from 'motion/react';
import { Undo2 } from 'lucide-react';
import { FaThumbsDown, FaThumbsUp } from 'react-icons/fa6';
import useMeasure from 'react-use-measure';
import { cn } from '@/lib/utils';
import type { IconType } from 'react-icons';

export type FeedbackStatus = 'idle' | 'up' | 'down';

export interface QuickFeedbackProps {
  defaultStatus?: FeedbackStatus;
  showThemeToggle?: boolean;
  feedbackText?: string;
  onFeedback?: (status: 'up' | 'down') => void;
  onUndo?: () => void;
}

const containerTransition: Transition = {
  type: 'spring',
  stiffness: 150,
  damping: 15,
  mass: 1,
};

export const QuickFeedback: FC<QuickFeedbackProps> = ({
  defaultStatus = 'idle',
  feedbackText = 'Feedback Received!',
  onFeedback,
  onUndo,
}) => {
  const [status, setStatus] = useState<FeedbackStatus>(defaultStatus);

  const handleFeedback = (value: 'up' | 'down') => {
    setStatus(value);
    onFeedback?.(value);
  };

  const handleUndo = () => {
    setStatus('idle');
    onUndo?.();
  };

  return (
    <div className="relative flex w-full items-center justify-center gap-4 bg-transparent px-4 transition-colors duration-500">
      <MotionConfig transition={containerTransition}>
        <LayoutGroup>
          <div className="relative flex items-center justify-center gap-2">
            <AnimatePresence mode="sync" initial={false}>
              {(status === 'idle' || status === 'up') && (
                <QuickFeedbackButton
                  key="up-btn"
                  name="up"
                  handleFeedback={() => handleFeedback('up')}
                  handleUndo={handleUndo}
                  status={status}
                  feedbackText={feedbackText}
                  Icon={FaThumbsUp}
                />
              )}
              {(status === 'idle' || status === 'down') && (
                <QuickFeedbackButton
                  key="down-btn"
                  name="down"
                  handleFeedback={() => handleFeedback('down')}
                  handleUndo={handleUndo}
                  status={status}
                  feedbackText="Sorry about that"
                  Icon={FaThumbsDown}
                />
              )}
            </AnimatePresence>
          </div>
        </LayoutGroup>
      </MotionConfig>
    </div>
  );
};

interface QuickFeedbackButtonProps {
  name: 'up' | 'down';
  handleFeedback: () => void;
  handleUndo: () => void;
  status: FeedbackStatus;
  feedbackText: string;
  Icon: IconType;
}

export const QuickFeedbackButton: FC<QuickFeedbackButtonProps> = ({
  name,
  handleFeedback,
  handleUndo,
  status,
  feedbackText,
  Icon,
}) => {
  const [ref, bounds] = useMeasure({ offsetSize: true });
  const isActive = name === status;

  return (
    <motion.div
      layout="position"
      animate={{
        opacity: 1,
        width: bounds.width > 0 ? bounds.width : 'auto',
        height: bounds.height > 0 ? bounds.height : 'auto',
      }}
      className="relative overflow-hidden rounded-full bg-[#F3EFE9] will-change-transform dark:border-neutral-800 dark:bg-neutral-900"
    >
      <motion.div
        ref={ref}
        className={cn(
          'flex w-fit items-center justify-center gap-1 px-12 py-3',
          isActive && 'px-4.5 py-3.5',
        )}
      >
        <motion.button
