import React, { useState, useEffect } from 'react';
import { motion, AnimatePresence, MotionConfig } from 'motion/react';
import { BsCheckCircleFill } from 'react-icons/bs';
import { cn } from '@/lib/utils';
import { useTheme } from 'next-themes';

type ButtonStatus = 'idle' | 'loading' | 'success' | 'saved';
type Size = 'sm' | 'md' | 'lg';

const SIZE_CONFIG = {
  sm: {
    height: 52,
    circleWidth: 52,
    idleWidth: 108,
    savedWidth: 128,
    text: 'text-[18px]',
    icon: 'text-2xl',
    spinner: 'w-7 h-7',
    gap: 'gap-2',
    padding: 'px-4',
  },
  md: {
    height: 56,
    circleWidth: 56,
    idleWidth: 120,
    savedWidth: 140,
    text: 'text-[20px]',
    icon: 'text-3xl',
    spinner: 'w-8 h-8',
    gap: 'gap-3',
    padding: 'px-5',
  },
  lg: {
    height: 68,
    circleWidth: 68,
    idleWidth: 144,
    savedWidth: 168,
    text: 'text-[22px]',
    icon: 'text-[28px]',
    spinner: 'w-9 h-9',
    gap: 'gap-4',
    padding: 'px-5',
  },
};

interface SaveToggleProps {
  size?: Size;
  idleText?: string;
  savedText?: string;
  loadingDuration?: number;
  successDuration?: number;
  onStatusChange?: (status: ButtonStatus) => void;
}

export const SaveToggle: React.FC<SaveToggleProps> = ({
  size = 'md',
  idleText = 'Save',
  savedText = 'Saved',
  loadingDuration = 1000,
  successDuration = 800,
  onStatusChange,
}) => {
  const [status, setStatus] = useState<ButtonStatus>('idle');
  const { theme } = useTheme();

  const cfg = SIZE_CONFIG[size];

  const stableWidth = Math.max(cfg.idleWidth, cfg.savedWidth);

  useEffect(() => {
    onStatusChange?.(status);
  }, [status, onStatusChange]);

  const handleClick = () => {
    if (status === 'idle') {
      setStatus('loading');

      setTimeout(() => {
        setStatus('success');

        setTimeout(() => {
          setStatus('saved');
        }, successDuration);
      }, loadingDuration);
    } else if (status === 'saved') {
      setStatus('idle');
    }
  };

  const isCircle = status === 'loading' || status === 'success';

  const getBackgroundColor = () => {
    if (status === 'loading' || status === 'success') {
      return theme === 'dark' ? '#ffffff' : '#18181b';
    }
    if (status === 'saved') {
      return theme === 'dark' ? '#27272a' : '#ffffff';
    }
    return theme === 'dark' ? '#27272a' : '#E8E7E0';
  };

  const getBorderColor = () => {
    if (status === 'saved') {
      return theme === 'dark' ? '#ffffff10' : '#00000030';
    }
    return 'transparent';
  };

  const getCheckColor = () => {
    if (status === 'success') {
      return theme === 'dark' ? '#27272a' : '#ffffff';
    }
    return theme === 'dark' ? '#a1a1aa' : '#27272a';
  };

  return (
    <div className="flex items-center justify-center p-10">
      <MotionConfig
        transition={{
          type: 'spring',
          stiffness: 400,
          damping: 30,
          mass: 1,
        }}
      >
        <motion.button
          onClick={handleClick}
          initial={false}
          animate={{
            width: isCircle ? cfg.circleWidth : stableWidth,
            height: cfg.height,
            backgroundColor: getBackgroundColor(),
          }}
          style={{
            borderWidth: status === 'saved' ? '2px' : '0',
            borderColor: getBorderColor(),
          }}
          transition={{
            type: 'spring',
            stiffness: 200,
            damping: 15,
            mass: 1.2,
            backgroundColor: {
              duration: 0.2,
            },
          }}
          className={cn(
            'relative z-0 flex cursor-pointer items-center justify-center overflow-hidden rounded-full select-none focus:outline-none active:scale-[0.97]',
          )}
        >
          <AnimatePresence mode="popLayout">
            {status === 'idle' && (
              <motion.span
                key="idle"
                initial={{ opacity: 0, y: 15 }}
                animate={{ opacity: 1, y: 0 }}
