                  exit={{ opacity: 0, y: 40, filter: 'blur(4px)' }}
                >
                  <div className="relative flex h-10 items-center justify-between overflow-hidden rounded-full border bg-neutral-100 dark:border-neutral-700 dark:bg-neutral-800">
