                      className="flex h-10 w-10 shrink-0 items-center justify-center text-neutral-400 hover:text-neutral-600 dark:hover:text-neutral-200"
                      onClick={() => setIsOpen(false)}
                    >
                      <HugeiconsIcon
                        icon={Cancel01Icon}
                        size={18}
                        strokeWidth={2}
                      />
                    </button>
                  </div>
                </motion.div>
              )}
            </AnimatePresence>

            <div className="relative flex items-center justify-end gap-2 p-2 px-3">
              <motion.button
                layoutId="container"
                className="flex size-10 items-center justify-center border bg-neutral-100 text-neutral-500 dark:border-neutral-700 dark:bg-neutral-800"
                style={{
                  borderRadius: 25,
                  opacity: isOpen ? 0 : 1,
                }}
                onClick={() => setIsOpen(true)}
              >
                <motion.span
                  layout="size"
                  initial={{
                    opacity: 0,
                  }}
                  animate={{
                    opacity: 1,
                  }}
                  exit={{
                    opacity: 0,
                  }}
                  transition={{
                    type: 'spring',
                    bounce: 0,
                    delay: 0.175,
                    duration: 0.4,
                  }}
                >
                  <BsCalendar3 size={18} />
                </motion.span>
              </motion.button>

              <motion.button
                className="origin-right bg-neutral-900 px-8 py-2 text-white dark:bg-neutral-100 dark:text-neutral-900 font-semibold"
                style={{ borderRadius: 25 }}
                animate={{
                  scale: isOpen ? 0.9 : 1,
                  transition: {
                    type: 'spring',
                    bounce: 0,
                    delay: isOpen ? 0.175 : 0,
                    duration: 0.4,
                  },
                }}
              >
                Post
              </motion.button>

              <AnimatePresence>
                {isOpen && (
                  <div className="absolute inset-0 z-20 flex size-full items-center justify-center p-2 px-3">
                    <motion.button
                      layoutId="container"
                      className="h-10 w-full bg-neutral-900 px-8 py-2 text-white dark:bg-neutral-100 dark:text-neutral-900 font-semibold"
                      style={{ borderRadius: 25 }}
                    >
                      <motion.span
                        layout="size"
                        initial={{
                          opacity: 0,
                        }}
                        animate={{
                          opacity: 1,
                        }}
                        exit={{
                          opacity: 0,
                        }}
                        transition={{
                          type: 'spring',
                          bounce: 0,
                          delay: 0.175,
                          duration: 0.4,
                        }}
                      >
                        Schedule
                      </motion.span>
                    </motion.button>
                  </div>
                )}
              </AnimatePresence>
            </div>
          </div>
        </motion.div>

        <AnimatePresence>
          {isOpen && (
            <motion.div
              layout
              initial={{ opacity: 0, y: -40 }}
              animate={{ opacity: 1, y: 0 }}
              exit={{ opacity: 0, y: -40 }}
              transition={{
                type: 'spring',
                bounce: 0,
                duration: 0.5,
                delay: 0.1,
