              range.start &&
              range.end &&
              currentDayDate > range.start &&
              currentDayDate < range.end;

            return (
              <div
                key={day}
                onClick={() => handleDateClick(currentDayDate)}
                className="group relative flex h-8 cursor-pointer items-center justify-center"
              >
                {(isInRange || isStart || isEnd) && (
