'use client';

import { useEffect, useRef, useState } from 'react';
import { createPortal } from 'react-dom';
import { AnimatePresence, motion, MotionConfig } from 'motion/react';
import { ChevronDown } from 'lucide-react';
import { cn } from '@/lib/utils';
import useMeasure from 'react-use-measure';

export interface Topic {
  id: string;
  title: string;
  content: string;
}

export interface ScrollIslandProps {
  topics: Topic[];
}

declare module 'react' {
  interface StyleHTMLAttributes<T> extends React.HTMLAttributes<T> {
    jsx?: boolean;
    global?: boolean;
  }
}

export function ScrollIsland({ topics }: ScrollIslandProps) {
  const [isOpen, setIsOpen] = useState(false);
  const [scrollProgress, setScrollProgress] = useState(0);
  const [activeTopicId, setActiveTopicId] = useState<string | null>(null);
  const [mounted, setMounted] = useState(false);
  const [ref, bounds] = useMeasure({ offsetSize: true });

  const contentRef = useRef<HTMLDivElement>(null);
  const [islandPosition, setIslandPosition] = useState({
    left: 0,
    top: 0,
    width: 0,
  });

  useEffect(() => {
    requestAnimationFrame(() => setMounted(true));

    const el = contentRef.current;
    if (!el) return;

    const updatePosition = () => {
      const { left, top, width } = el.getBoundingClientRect();
      setIslandPosition({ left, top, width });
    };
    const observer = new ResizeObserver(updatePosition);
    observer.observe(el);
    updatePosition();

    const handleScroll = () => {
      const scrollTop = el.scrollTop;
      const scrollHeight = el.scrollHeight - el.clientHeight;

      if (scrollHeight > 0) {
        const progress = (scrollTop / scrollHeight) * 100;
        setScrollProgress(Math.min(100, Math.max(0, progress)));
      }
    };

    el.addEventListener('scroll', handleScroll);
    handleScroll();

    return () => {
      observer.disconnect();
      el.removeEventListener('scroll', handleScroll);
    };
  }, []);

  const handleTopicClick = (id: string) => {
    setActiveTopicId(id);
    setTimeout(() => setActiveTopicId(null), 1800);
    setIsOpen(false);
  };

  const islandUI = (
    <>
      <MotionConfig
        transition={{
          type: 'spring',
          bounce: 0.2,
          duration: 0.7,
        }}
      >
        <div
          className="pointer-events-none fixed z-9999 flex justify-center pt-6"
          style={islandPosition}
        >
          <motion.div
            className={cn(
              'pointer-events-auto flex flex-col items-center overflow-hidden border border-white/10 bg-neutral-900 shadow-2xl',
            )}
            initial={{
              borderRadius: 32,
            }}
            animate={{
              height: bounds.height > 0 ? bounds.height : 'auto',
              width: isOpen ? 400 : 240,
              borderRadius: isOpen ? 24 : 32,
            }}
          >
            <div
              ref={ref}
              className={cn(
                'flex flex-col items-center  px-4 w-full',
                isOpen && '',
              )}
            >
              <div
                className="group flex h-13 w-full cursor-pointer items-center justify-between gap-8 select-none"
                onClick={() => setIsOpen(!isOpen)}
              >
                <div className="flex items-center gap-2">
                  <motion.div
                    layout
                    className="relative h-7 w-7 shrink-0 rounded-full"
                    style={{
                      background: `conic-gradient(white ${scrollProgress}%, #333 0)`,
                    }}
                  >
                    <div className="absolute inset-[2.5px] rounded-full bg-black" />
                    <div className="absolute inset-0 flex items-center justify-center"></div>
                  </motion.div>

                  <motion.span
                    layout
                    className="text-lg font-medium text-white"
                  >
                    Index
                  </motion.span>

                  <motion.div layout animate={{ rotate: isOpen ? 180 : 0 }}>
                    <ChevronDown
                      size={20}
                      className="text-neutral-400 group-hover:text-white"
                    />
                  </motion.div>
                </div>

                <motion.div
                  layout
                  className="flex items-center justify-center rounded-full bg-zinc-800 px-2.5 text-lg tabular-nums font-bold text-zinc-200"
                >
                  {Math.round(scrollProgress)}%
                </motion.div>
              </div>

              <AnimatePresence mode="popLayout">
                {isOpen && (
                  <motion.div
                    initial={{ opacity: 0 }}
                    animate={{ opacity: 1 }}
                    exit={{ opacity: 0 }}
                    className="custom-scrollbar w-full overflow-y-auto pt-2 pb-4"
                    style={{
                      maxHeight:
                        `max(0px, min(60dvh, calc(100dvh - ${islandPosition.top + 92}px)))`,
                    }}
                  >
                    <div className="mx-2 mb-2 h-px bg-white/5" />
                    {topics.map((topic) => (
                      <button
                        key={topic.id}
                        onClick={() => {
                          document.getElementById(topic.id)?.scrollIntoView({
                            behavior: 'smooth',
                            block: 'center',
                          });
                          handleTopicClick(topic.id);
                        }}
                        className="w-full truncate rounded-xl py-2 text-left text-sm text-zinc-400 hover:text-white"
                      >
                        {topic.title}
                      </button>
                    ))}
                  </motion.div>
                )}
              </AnimatePresence>
            </div>
          </motion.div>
        </div>

        <AnimatePresence>
          {isOpen && (
            <motion.div
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              exit={{ opacity: 0 }}
              className="fixed inset-0 z-9998 bg-black/40 backdrop-blur-sm"
              onClick={() => setIsOpen(false)}
            />
          )}
        </AnimatePresence>
      </MotionConfig>
    </>
  );

  return (
    <div className="relative w-full">
      <main
        ref={contentRef}
        className="px- mx-auto h-[calc(100vh-6rem)] max-w-4xl overflow-y-auto pt-32 pb-20"
      >
        {topics.map((topic) => (
          <div
            key={topic.id}
            id={topic.id}
            className={`mb-20 scroll-mt-32 rounded-2xl p-2 transition-all duration-500 ${activeTopicId === topic.id
                ? 'animate-flash bg-zinc-100 dark:bg-zinc-900'
                : ''
              }`}
          >
            <h4 className="mb-6 text-3xl font-bold text-zinc-900 dark:text-zinc-50">
              {topic.title}
            </h4>
            <p className="text-lg leading-relaxed text-zinc-600 dark:text-zinc-400">
              {topic.content}
            </p>
          </div>
        ))}
      </main>

      {mounted && createPortal(islandUI, document.body)}

      <style jsx global>{`
        @keyframes flash {
          0%,
          100% {
            background-color: transparent;
          }
          50% {
            background-color: rgba(255, 255, 255, 0.05);
          }
        }
        .animate-flash {
          animation: flash 0.6s ease-in-out 3;
        }
        .custom-scrollbar::-webkit-scrollbar {
          width: 3px;
        }
        .custom-scrollbar::-webkit-scrollbar-thumb {
          background: #333;
          border-radius: 10px;
        }
      `}</style>
    </div>
  );
}

