                      fill="currentColor"
                      strokeWidth={1.5}
                    />
                  </motion.div>
                  <motion.span layoutId="priority-text">
                    {data.priority}
                  </motion.span>
                </div>
                <div className="flex items-center gap-1 text-neutral-500 sm:gap-1.5 dark:text-neutral-400">
