  );

  const rotate = useTransform(scrollX, (s: number) => {
    const d = s + itemX;
    return (d / pixelsPerUnit) * 12;
  });

  return (
    <motion.div
      className="absolute top-0 flex flex-col items-center"
      style={{
        left: itemX,
