      }}
    >
      <motion.span
        className={`text-[56px] font-bold tracking-tight sm:text-[68px] ${isHalf ? 'invisible' : ''}`}
        style={{ color }}
      >
        {Math.floor(value)}
      </motion.span>

      <div className="mt-2 flex flex-col items-center sm:mt-4">
        <div
