  }
}

const localeMap = {
  en: enUS,
  hi
} as const

const numeralMap = {
  en: 'latn',
  hi: 'deva'
} as const

const isCalendarLocale = (value: string | null): value is CalendarLocale => value === 'en' || value === 'hi'

