      label: 'Last month',
      range: {
        from: startOfMonth(previousMonth),
        to: endOfMonth(previousMonth)
      }
    },
    {
      label: 'Next month',
      range: {
        from: startOfMonth(upcomingMonth),
        to: endOfMonth(upcomingMonth)
      }
    },
    {
      label: 'Year to date',
      range: {
        from: startOfYear(baseDate),
        to: baseDate
      }
    },
    {
      label: 'Last year',
      range: {
        from: startOfYear(previousYear),
        to: endOfYear(previousYear)
      }
    }
  ]
}

