import { Checkbox } from '@/components/base-ui/checkbox'

const snacks = ['Salad', 'Wrap', 'Juice'] as const

type Snack = (typeof snacks)[number]

const Checkbox6 = () => {
  const [selectedSnacks, setSelectedSnacks] = useState<Snack[]>([
    'Salad',
    'Wrap'
