                    alt={`${country.label} flag`}
                    className='h-4 w-5 rounded-[2px] object-cover'
                  />
                  <span className='min-w-0 flex-1 truncate'>{country.label}</span>
                </CommandItem>
              ))}
            </CommandList>
          </Command>
        </PopoverContent>
      </Popover>
    </div>
  )
}

