  Select,
  SelectContent,
  SelectGroup,
  SelectItem,
  SelectLabel,
  SelectTrigger,
  SelectValue
} from '@/components/base-ui/select'
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from '@/components/base-ui/table'

import { cn } from '@/lib/utils'

type Density = 'compact' | 'flexible' | 'standard'

type InvoiceStatus = 'failed' | 'paid' | 'processing' | 'review'

type ClientInvoice = {
  amount: number
  email: string
  id: string
  name: string
  status: InvoiceStatus
}

type DensityOption = {
  icon: typeof Rows2Icon
  label: string
  value: Density
}

const densityOptions: readonly DensityOption[] = [
  {
    value: 'compact',
    label: 'Compact',
    icon: Rows4Icon
  },
  {
    value: 'standard',
    label: 'Standard',
    icon: Rows3Icon
  },
  {
    value: 'flexible',
    label: 'Flexible',
    icon: Rows2Icon
  }
] as const

const data: readonly ClientInvoice[] = [
  {
    id: 'INV-101',
    name: 'Aurora Lab',
    amount: 699,
    status: 'paid',
    email: 'billing@auroralab.co'
  },
  {
    id: 'INV-102',
