type PaymentStatus = 'failed' | 'processing' | 'success'

type Payment = {
  amount: number
  email: string
  id: string
  name: string
  status: PaymentStatus
}

const data: readonly Payment[] = [
  {
    id: 'PAY-101',
    name: 'Shang Chain',
    amount: 699,
    status: 'success',
    email: 'shang07@yahoo.com'
  },
