                  <SelectValue placeholder="Choose your account" />
                </SelectTrigger>

                <SelectContent className="rounded-sm">
                  {accounts.map((acc) => (
                    <SelectItem
                      key={acc.email}
                      value={acc.email}
                      className="flex items-center gap-2"
                    >
                      <div className="flex items-center gap-2">
                        <Avatar className="h-6 w-6">
                          <AvatarImage
                            src={acc.avatar}
                            className="rounded-sm"
                          />
