              id={`${`${id}-${item.value}`}-price`}
              className="text-muted-foreground group-has-checked:text-foreground text-sm"
            >
              {item.price}
            </div>
          </div>
        </div>
      ))}
    </RadioGroup>
  );
};

export default RadioGroup10;

