        name: 'Subscriptions',
        icon: HiSquares2X2,
        type: 'page',
      },
      {
        name: 'Checkout Flow',
        icon: HiSquares2X2,
        type: 'page',
      },
    ],
  },
  {
    name: 'Conversations',
    icon: HiChatBubbleLeftRight,
    type: 'page',
  },
  {
    name: 'Inbox',
    icon: HiEnvelope,
    type: 'page',
  },
  {
    name: 'Planner',
    icon: HiCalendarDays,
    type: 'page',
  },
  {
    name: 'Commerce',
    icon: HiShoppingCart,
    type: 'category',
    children: [
      {
        name: 'Catalog',
        icon: HiShoppingCart,
        type: 'page',
      },
      {
        name: 'Collections',
        icon: HiShoppingCart,
        type: 'page',
      },
      {
        name: 'Orders',
        icon: HiShoppingCart,
        type: 'page',
      },
      {
        name: 'Regions',
        icon: HiShoppingCart,
        type: 'page',
      },
    ],
  },
  {
    name: 'Login',
    icon: HiArrowRightOnRectangle,
    type: 'page',
  },
  {
    name: 'Logout',
    icon: HiArrowLeftOnRectangle,
    type: 'page',
  },
  {
    name: 'Support',
    icon: HiHeart,
    type: 'page',
  },
  {
    name: 'Resources',
    icon: HiBookOpen,
    type: 'page',
  },
];

const NavigationMenu = ({
  item,
  level,
}: {
  level: number;
  item: NavigationItem;
}) => {
  if (item.type === 'page') {
    const Icon = item.icon;
    return (
      <div
        className="focus-visible:ring-ring/50 flex items-center gap-2 rounded-md p-1 outline-none focus-visible:ring-[3px]"
        style={{ paddingLeft: `${level === 0 ? 0.25 : 1.75}rem` }}
      >
        <Icon className="size-4 shrink-0" />
        <span className="text-sm">{item.name}</span>
      </div>
    );
  }

  const Icon = item.icon;

  return (
    <Collapsible
      className="flex flex-col gap-1.5"
      style={{ paddingLeft: `${level === 0 ? 0 : 1.5}rem` }}
    >
      <CollapsibleTrigger className="focus-visible:ring-ring/50 flex items-center gap-2 rounded-md p-1 outline-none focus-visible:ring-[3px]">
        <Icon className="size-4 shrink-0" />
        <span className="flex-1 text-start text-sm">{item.name}</span>
