    () => [...new Set(jobs.map((j) => j.location))],
    [jobs],
  );
  const types = useMemo(() => [...new Set(jobs.map((j) => j.type))], [jobs]);

  const filtered = useMemo(() => {
    let list = jobs;
    if (locationFilter)
      list = list.filter((j) => j.location === locationFilter);
    if (typeFilter) list = list.filter((j) => j.type === typeFilter);
