              >
                <div className="flex items-center gap-3">
                  <span
                    className={[
                      'shrink-0',
                      uf.status === 'error'
                        ? 'text-destructive'
                        : uf.status === 'done'
                          ? 'text-primary'
                          : 'text-muted-foreground',
                    ].join(' ')}
                  >
                    <FileIcon file={uf.file} />
                  </span>

                  <div className="flex min-w-0 flex-1 flex-col gap-0.5">
                    <p className="text-foreground truncate text-sm leading-none font-medium">
