            disabled={!allDone}
            onClick={handleSubmit}
            className="gap-1.5"
          >
            {submitLabel}
            <FaArrowRight className="size-3" />
          </Button>
        </div>
      </CardFooter>

      <input
        ref={inputRef}
        id="file-upload-input"
        type="file"
        multiple
        className="sr-only"
        onChange={handleInputChange}
        aria-hidden="true"
      />
    </Card>
  );
}

