          }`}
        >
          <Button
            type="button"
            variant="outline"
            size="lg"
            onClick={(event) => {
              event.stopPropagation();
              inputRef.current?.click();
            }}
            className="mb-4 gap-2"
          >
            <LuUpload className="h-4 w-4" />
            {uploadLabel}
