    ctaLabel = "Let's Move Forward Today",
    ctaHref = "#",
    description = "Advanced wind turbines that take energy\n production to new heights.",
    socialLinks = DEFAULT_SOCIAL,
    signInLabel = "Sign in",
    signInHref = "#",
    onNavLinkClick,
    className,
