                    }}
                />
            </motion.div>

            {/* ── Header / Navbar ── */}
            <motion.header
                initial={{ opacity: 0, y: -10 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ duration: 0.6, ease: "easeOut" }}
                className="relative z-50 flex items-center justify-between px-6 py-6 md:px-12 lg:px-20"
            >
                {/* Brand Logo */}
