          className="group flex items-center gap-2 text-[15px] font-medium text-[#1C201A] transition-colors hover:text-black"
        >
          Talk to our team
          <HugeiconsIcon
            icon={ArrowRight01Icon}
            className="size-4 transition-transform group-hover:translate-x-1"
          />
        </a>
      </motion.div>
    </section>
  );
}

