            checked={isYearly}
            onCheckedChange={setIsYearly}
          />
          <Label
            htmlFor="billing-toggle"
            className={cn(
              'cursor-pointer text-sm font-medium transition-colors',
              isYearly ? 'text-foreground' : 'text-muted-foreground',
