    bio: 'A technical mastermind, Cody specializes in building robust, scalable architectures and leading high-performing engineering teams.',
    socials: [
      { icon: 'github', url: '#' },
      { icon: 'linkedin', url: '#' },
      { icon: 'twitter', url: '#' }
    ]
  },
  {
    id: '3',
