            <span
              className="size-3 rounded-xs"
              style={{ backgroundColor: CHART_THEME_COLORS.heatmap.low }}
            />
            <span
              className="size-3 rounded-xs"
              style={{ backgroundColor: CHART_THEME_COLORS.heatmap.med }}
            />
            <span
              className="size-3 rounded-xs"
              style={{ backgroundColor: CHART_THEME_COLORS.heatmap.high }}
            />
          </div>
          <span>High</span>
        </div>
      </div>

      <div className="h-64 w-full min-w-0">
        <ResponsiveContainer width="100%" height="100%">
          <ScatterChart margin={{ top: 8, right: 8, left: 8, bottom: 12 }}>
            <XAxis
              type="number"
              dataKey="x"
              domain={[-0.5, 6.5]}
              ticks={[0, 2, 4, 6]}
              tickFormatter={(val: number) =>
                dateLabels[Math.round(val / 2)] || ''
              }
              axisLine={false}
              tickLine={false}
              tick={AXIS_TICK}
            />
            <YAxis
              type="number"
              dataKey="y"
              domain={[-0.5, 4.5]}
              hide
            />
            <Tooltip cursor={false} content={<HeatmapScatterTooltip />} />
            <Scatter
              data={scatterData}
              shape={(props: any) => {
                const { xAxis, yAxis, cx, cy, payload } = props
                if (typeof cx !== 'number' || typeof cy !== 'number') return <g />
                const colW = (xAxis?.width ?? 0) / 7
                const rowH = (yAxis?.height ?? 0) / 5
                const w = Math.max(colW - 6, 8)
                const h = Math.max(rowH - 4, 8)

                return (
                  <rect
                    x={cx - w / 2}
                    y={cy - h / 2}
                    width={w}
                    height={h}
                    rx={6}
                    className="transition-opacity duration-200 hover:opacity-75 cursor-pointer"
                    fill={tileDotColorMap[payload.level as HeatmapTile]}
                  />
                )
              }}
              isAnimationActive
              animationDuration={CHART_ANIMATION_MS}
            />
          </ScatterChart>
        </ResponsiveContainer>
      </div>
    </article>
  )
}

import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useState,
  type ReactNode,
} from 'react'

export type Theme = 'dark' | 'light' | 'system'

type ThemeProviderProps = {
  children: ReactNode
  defaultTheme?: Theme
  storageKey?: string
}

type ThemeProviderState = {
  theme: Theme
  resolvedTheme: 'dark' | 'light'
  setTheme: (theme: Theme) => void
  toggleTheme: () => void
}

const ThemeProviderContext = createContext<ThemeProviderState | null>(null)

function getSystemTheme(): 'dark' | 'light' {
  if (typeof window === 'undefined') return 'light'
  return window.matchMedia('(prefers-color-scheme: dark)').matches
    ? 'dark'
    : 'light'
}

export function ThemeProvider({
  children,
  defaultTheme = 'light',
  storageKey = 'bionis-theme',
}: ThemeProviderProps) {
  const [theme, setThemeState] = useState<Theme>(() => {
    if (typeof window === 'undefined') return defaultTheme
    const stored = localStorage.getItem(storageKey) as Theme | null
    return stored ?? defaultTheme
  })

  const resolvedTheme = useMemo(
    () => (theme === 'system' ? getSystemTheme() : theme),
    [theme],
  )

  useEffect(() => {
    if (typeof window === 'undefined') return
    const root = window.document.documentElement
    root.classList.remove('light', 'dark')
    root.classList.add(resolvedTheme)
  }, [resolvedTheme])

  const setTheme = useCallback(
    (next: Theme) => {
      if (typeof window !== 'undefined') {
        localStorage.setItem(storageKey, next)
      }
      setThemeState(next)
    },
    [storageKey],
  )

  const toggleTheme = useCallback(() => {
    const nextTheme = resolvedTheme === 'dark' ? 'light' : 'dark'
    setTheme(nextTheme)
  }, [resolvedTheme, setTheme])

  const value = useMemo(
    () => ({ theme, resolvedTheme, setTheme, toggleTheme }),
    [theme, resolvedTheme, setTheme, toggleTheme],
  )

  return (
    <ThemeProviderContext.Provider value={value}>
      {children}
    </ThemeProviderContext.Provider>
  )
}

export function useTheme() {
  const context = useContext(ThemeProviderContext)
  if (!context) {
    throw new Error('useTheme must be used within a ThemeProvider')
  }
  return context
}

