export function ModellingDashboard() {
  const [selectedRegion, setSelectedRegion] = useState<NetworkRegion | null>(
    null,
  )
  const [isMobile, setIsMobile] = useState(() =>
    typeof window === "undefined"
      ? false
      : !window.matchMedia("(min-width: 48rem)").matches,
  )

  useEffect(() => {
    const desktopQuery = window.matchMedia("(min-width: 48rem)")
    const syncViewport = () => setIsMobile(!desktopQuery.matches)

    syncViewport()
    desktopQuery.addEventListener("change", syncViewport)
    return () => desktopQuery.removeEventListener("change", syncViewport)
  }, [])

  const clearSelection = () => setSelectedRegion(null)

  return (
    <div className="absolute inset-x-0 bottom-0 top-18 overflow-hidden bg-background md:left-17">
      <Map
        selectedRegion={selectedRegion}
        onSelectRegion={setSelectedRegion}
      />
      {selectedRegion && (
        <>
          <DesktopInformationPanel
            region={selectedRegion}
            onCollapse={clearSelection}
          />
          <MobileInformationDrawer
            region={selectedRegion}
            open={isMobile}
            onCollapse={clearSelection}
          />
        </>
      )}
    </div>
  )
}

import { useEffect, useState, type ReactNode } from "react"

import { TooltipProvider } from "@/components/ui/tooltip"

import { AppSidebar } from "./app-sidebar"
import { TopNavbar } from "./top-navbar"

export function DashboardShell({ children }: { children: ReactNode }) {
  const [isDark, setIsDark] = useState(() =>
    typeof document === "undefined"
      ? false
      : document.documentElement.classList.contains("dark")
  )

  useEffect(() => {
    const root = document.documentElement
    const syncTheme = () => setIsDark(root.classList.contains("dark"))
    const observer = new MutationObserver(syncTheme)

    syncTheme()
    observer.observe(root, {
      attributes: true,
      attributeFilter: ["class"],
    })

    return () => observer.disconnect()
  }, [])

  function handleThemeChange(dark: boolean) {
    document.documentElement.classList.toggle("dark", dark)
    localStorage.setItem("theme", dark ? "dark" : "light")
    setIsDark(dark)
  }

  return (
    <TooltipProvider>
      <div
        className="gridline-dashboard relative h-svh min-h-0 overflow-hidden transition-colors"
      >
        <AppSidebar />
        <TopNavbar
          isDark={isDark}
          onThemeChange={handleThemeChange}
        />

        <main
          aria-label="Page content"
          className="h-full overflow-y-auto pt-18 md:pl-17"
        >
          {children}
        </main>
      </div>
    </TooltipProvider>
  )
}

import {
  Tooltip,
  TooltipContent,
  TooltipTrigger,
} from "@/components/ui/tooltip";
import { buttonVariants } from "@/components/ui/button";
import { cn } from "@/lib/utils";
import type { LucideIcon } from "lucide-react";

import { useDashboardNavigation } from "../navigation";

export type NavigationItem = {
  href: string;
  label: string;
  shortLabel: string;
  icon: LucideIcon;
};

type SidebarNavigationItemProps = {
  item: NavigationItem;
  showLabel?: boolean;
  onNavigate?: () => void;
};

export function SidebarNavigationItem({
  item,
  showLabel = false,
  onNavigate,
}: SidebarNavigationItemProps) {
  const { pathname, navigate } = useDashboardNavigation();
  const active =
    item.href === "/"
      ? pathname === item.href
      : pathname.startsWith(item.href);
  const Icon = item.icon;
  const className = cn(
    buttonVariants({
      variant: "ghost",
      size: showLabel ? "lg" : "icon-lg",
    }),
    "rounded-lg text-muted-foreground",
    showLabel && "w-full justify-start gap-3",
    active &&
      "bg-primary/10 text-primary hover:bg-primary/20 hover:text-primary",
  );

  const content = (
    <>
      <Icon
        aria-hidden="true"
        className={showLabel ? "size-5" : "size-6"}
        strokeWidth={showLabel ? 1.7 : 1.6}
      />
      {showLabel && item.shortLabel}
    </>
  );
  const handleNavigate = () => {
    navigate(item.href);
    onNavigate?.();
  };

  if (showLabel) {
    return (
      <button
        type="button"
        aria-current={active ? "page" : undefined}
        className={className}
        onClick={handleNavigate}
      >
        {content}
      </button>
    );
  }

  return (
    <Tooltip>
      <TooltipTrigger
        type="button"
        aria-label={item.label}
        aria-current={active ? "page" : undefined}
        className={className}
        onClick={handleNavigate}
      >
        {content}
      </TooltipTrigger>
      <TooltipContent side="right">{item.label}</TooltipContent>
    </Tooltip>
  );
}

