                      'bg-(--status-exception)/15 text-(--status-exception)',
                    transaction.status === 'completed' &&
                      'bg-(--status-completed)/15 text-(--status-completed)',
                    transaction.status === 'processing' &&
                      'bg-(--status-processing)/15 text-(--status-processing)',
